    ProductVariant = apps.get_model("catalog", "ProductVariant")

    grind_by_slug = {}
    for slug, name, order in GRIND_SEED:
        obj, _ = GrindType.objects.get_or_create(
            slug=slug, defaults={"name": name, "order": order, "is_active": True}
        )
        grind_by_slug[slug] = obj
    roast_by_slug = {}
    for slug, name, order in ROAST_SEED:
        obj, _ = RoastType.objects.get_or_create(
            slug=slug, defaults={"name": name, "order": order, "is_active": True}
        )
        roast_by_slug[slug] = obj
    default_roast = roast_by_slug["medium"]

    # Переносим каждый старый вариант (product, weight, grind, price) в новую структуру.
    for v in ProductVariant.objects.all():
        pkg, _ = ProductPackaging.objects.get_or_create(
            product_id=v.product_id, weight=v.weight or 0,
            defaults={"price": v.price or 0, "old_price": v.old_price, "order": v.weight or 0},
        )
        # Если фасовка уже была создана с нулевой ценой — обновим из варианта.
        if (not pkg.price) and v.price:
            pkg.price = v.price
            pkg.old_price = v.old_price
            pkg.save()

        grind = grind_by_slug.get(v.grind) or grind_by_slug["whole"]
        # Обжарка варианта = по уровню обжарки товара (атрибут), иначе «Средняя».
        roast = default_roast
        try:
            lvl = v.product.roast_level
            if lvl in PRODUCT_ROAST_MAP:
                roast = roast_by_slug[PRODUCT_ROAST_MAP[lvl]]
        except Exception:
            pass

        v.packaging = pkg
        v.grind_type = grind
        v.roast_type = roast
        v.save(update_fields=["packaging", "grind_type", "roast_type"])


